/* Original-skin storage window, independent from dialogue glyph batching. */
static void npc_storage_panel64(NpcGame55*g){NpcStorage64*u=&g->storage64;Combat*game=g->player.game;unsigned count=npc_storage_count64(game,u->box),first=u->row/10*10;ui_panel(95,58,450,354,"Storage",0,-1);pb_fill(104,82,432,24,0xffeaf0f5);ui_bold_fit47(112,86,410,u->box?"Storage - withdraw to inventory":"Inventory - deposit in storage");for(unsigned i=first;i<count&&i<first+10;i++){const OwnedItem52*p=npc_storage_item64(game,u->box,i);int item=inventory_catalog52(p->sourceID),y=112+(i-first)*24;ui_cell(104,y,432,23,i==u->row);if(item>=0){skin_icon(itemIcons[item],110,y+3,18,18);ui_fit47(134,y+3,306,1,itemDefs[item].name);}ui_scaled(458,y+3,1,"%u",p->quantity);}if(!count)ui_scaled(112,119,1,"No items.");char amount[24];if(u->quantity)snprintf(amount,sizeof(amount),"%u",u->quantity);else strcpy(amount,"all");ui_scaled(111,356,.9f,"Quantity: %s | Inventory %u/100 | Storage %u/600",amount,npc_storage_count64(game,0),npc_storage_count64(game,2));ui_hint64(111,379,.85f,"LEFT/RIGHT: bank  UP/DOWN: item  A: transfer");ui_hint64(111,394,.85f,"X: quantity  B: close");}
